def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def blocks(n, separators):
        cuts = [-1] + separators + [n]
        return [(cuts[i] + 1, cuts[i + 1])
                for i in range(len(cuts) - 1)
                if cuts[i] + 1 < cuts[i + 1]]

    row_blocks, col_blocks = blocks(h, sep_rows), blocks(w, sep_cols)
    separator_colors = {grid[r][0] for r in sep_rows}
    separator_colors.update(grid[0][c] for c in sep_cols)

    from collections import Counter
    counts = Counter(grid[r][c] for a, b in row_blocks for x, y in col_blocks
                     for r in range(a, b) for c in range(x, y))
    spot = min(counts, key=counts.get)
    background = max((color for color in counts if color != spot),
                     key=lambda color: counts[color])

    return [
        [1 if sum(grid[r][c] == spot for r in range(a, b) for c in range(x, y)) >= 2
         else background for x, y in col_blocks]
        for a, b in row_blocks
    ]
